'use client';

import { useId, useState } from 'react';

import { InfoIcon, RotateCcwIcon, SendIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Input } from '@/registry/ndeko/ui/input';
import { Switch } from '@/registry/ndeko/ui/switch';

import { ActionButton, useTimedAction } from './_parts/action-button';
import { ChoiceSegments, type SegmentOption } from './_parts/choice-segments';
import { isEmail } from './_parts/invite-emails';
import {
  ModalCloseButton,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { Swap } from './_parts/swap';

type Role = 'admin' | 'editor' | 'viewer';

type PermissionId = 'create' | 'edit' | 'delete' | 'invite' | 'reports';

type Permissions = Record<PermissionId, boolean>;

const ROLE_OPTIONS: SegmentOption<Role>[] = [
  { value: 'admin', label: 'Admin' },
  { value: 'editor', label: 'Editor' },
  { value: 'viewer', label: 'Viewer' },
];

const PERMISSIONS: { id: PermissionId; label: string; line: string }[] = [
  {
    id: 'create',
    label: 'Create tasks',
    line: 'Adds tasks and sub-tasks to any project',
  },
  {
    id: 'edit',
    label: 'Edit the tasks of others',
    line: 'Changes their status, dates and assignees',
  },
  {
    id: 'delete',
    label: 'Delete tasks',
    line: 'Removes tasks for good, with their time',
  },
  {
    id: 'invite',
    label: 'Invite people',
    line: 'Sends invitations to the workspace',
  },
  {
    id: 'reports',
    label: 'See reports',
    line: 'Opens the time and payment reports',
  },
];

const PRESETS: Record<Role, Permissions> = {
  admin: {
    create: true,
    edit: true,
    delete: true,
    invite: true,
    reports: true,
  },
  editor: {
    create: true,
    edit: true,
    delete: false,
    invite: false,
    reports: true,
  },
  viewer: {
    create: false,
    edit: false,
    delete: false,
    invite: false,
    reports: true,
  },
};

const PERMISSION_IDS: PermissionId[] = PERMISSIONS.map(
  (permission) => permission.id
);

function roleLabelOf(role: Role) {
  const option = ROLE_OPTIONS.find((candidate) => candidate.value === role);
  return option?.label ?? role;
}

function differsFromPreset(permissions: Permissions, role: Role) {
  const preset = PRESETS[role];
  return PERMISSION_IDS.some((id) => permissions[id] !== preset[id]);
}

function PermissionRow({
  label,
  line,
  checked,
  onCheckedChange,
}: {
  label: string;
  line: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}) {
  const switchId = useId();

  return (
    <div className='flex items-center justify-between gap-4 py-1.5'>
      <div className='flex min-w-0 flex-col gap-0.5'>
        <label htmlFor={switchId} className='text-[13px] font-medium'>
          {label}
        </label>
        <p className='text-muted-foreground text-xs'>{line}</p>
      </div>
      <Switch
        id={switchId}
        checked={checked}
        onCheckedChange={onCheckedChange}
      />
    </div>
  );
}

function ManageAccess() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<Role>('editor');
  const [permissions, setPermissions] = useState<Permissions>(PRESETS.editor);
  const [error, setError] = useState<string | null>(null);
  const [sentLine, setSentLine] = useState<string | null>(null);
  const action = useTimedAction();
  const emailId = useId();
  const hintId = useId();
  const roleLabel = roleLabelOf(role);
  const isCustom = differsFromPreset(permissions, role);
  const hasError = Boolean(error);
  const hasSentLine = Boolean(sentLine);
  const hint = error ?? 'They get an e-mail invitation to join';
  const permissionsKey = String(isCustom);

  function changeEmail(event: React.ChangeEvent<HTMLInputElement>) {
    setEmail(event.target.value);
    setError(null);
  }

  function changeRole(nextRole: Role) {
    setRole(nextRole);
    setPermissions(PRESETS[nextRole]);
  }

  function resetPermissions() {
    setPermissions(PRESETS[role]);
  }

  function changePermission(id: PermissionId, checked: boolean) {
    setPermissions((previous) => ({ ...previous, [id]: checked }));
  }

  function commitSend() {
    const address = email.trim().toLowerCase();
    setSentLine(`Invitation sent to ${address} as ${roleLabel}`);
    setEmail('');
  }

  function send(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const address = email.trim().toLowerCase();
    if (!isEmail(address)) {
      setError('Enter an address like name@company.com');
      return;
    }
    action.run(commitSend);
  }

  return (
    <form onSubmit={send} className='flex flex-col gap-5' noValidate>
      <ModalHeader>
        <ModalTitle>Manage access</ModalTitle>
        <ModalDescription>
          Invite someone and choose exactly what they can do
        </ModalDescription>
      </ModalHeader>
      <div className='flex flex-col gap-1.5'>
        <label htmlFor={emailId} className='text-[13px] font-medium'>
          E-mail address
        </label>
        <Input
          id={emailId}
          type='email'
          autoComplete='off'
          placeholder='name@company.com'
          value={email}
          aria-invalid={hasError}
          aria-describedby={hintId}
          onChange={changeEmail}
        />
        <p
          id={hintId}
          className={cn(
            'flex items-center gap-1.5 text-xs',
            hasError && 'text-destructive-ink',
            !hasError && 'text-muted-foreground'
          )}
        >
          <InfoIcon className='size-3.5 shrink-0' />
          <Swap swapKey={hint} kind='label'>
            {hint}
          </Swap>
        </p>
      </div>
      <div className='flex flex-col gap-2'>
        <span className='text-[13px] font-medium'>Role</span>
        <ChoiceSegments
          label='Role'
          value={role}
          options={ROLE_OPTIONS}
          onValueChange={changeRole}
        />
      </div>
      <div className='flex flex-col gap-1'>
        <div className='flex min-h-7 items-center justify-between gap-3'>
          <span className='text-[13px] font-medium'>Permissions</span>
          <Swap swapKey={permissionsKey} kind='label'>
            {isCustom && (
              <span className='flex items-center gap-1'>
                <Chip color='var(--warning)'>Custom</Chip>
                <Button
                  variant='ghost'
                  size='sm'
                  onClick={resetPermissions}
                  className='text-muted-foreground'
                >
                  <RotateCcwIcon />
                  {`Reset to ${roleLabel}`}
                </Button>
              </span>
            )}
            {!isCustom && (
              <span className='text-muted-foreground text-xs'>
                {`Set by the ${roleLabel} role`}
              </span>
            )}
          </Swap>
        </div>
        {PERMISSIONS.map((permission) => {
          function changeThis(checked: boolean) {
            changePermission(permission.id, checked);
          }

          return (
            <PermissionRow
              key={permission.id}
              label={permission.label}
              line={permission.line}
              checked={permissions[permission.id]}
              onCheckedChange={changeThis}
            />
          );
        })}
      </div>
      <AnimatedSize>
        {hasSentLine && (
          <Swap
            swapKey={sentLine ?? ''}
            kind='label'
            className='text-muted-foreground flex min-w-0 text-xs'
            contentClassName='max-w-full min-w-0 whitespace-normal'
          >
            {sentLine}
          </Swap>
        )}
      </AnimatedSize>
      <ModalFooter>
        <ModalCloseButton variant='ghost'>Cancel</ModalCloseButton>
        <ActionButton
          type='submit'
          state={action.state}
          idleIcon={<SendIcon />}
          labels={{
            idle: 'Send invitation',
            working: 'Sending',
            done: 'Sent',
          }}
        />
      </ModalFooter>
    </form>
  );
}

export default function Modal06() {
  return (
    <ModalPreview triggerLabel='Open the access dialog' size='md'>
      <ManageAccess />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import type { Icon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

export type SegmentOption<Value extends string> = {
  value: Value;
  label: string;
  icon?: Icon;
};

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

type ChoiceSegmentsProps<Value extends string> = {
  value: Value;
  options: SegmentOption<Value>[];
  onValueChange: (value: Value) => void;
  /** Names the group for screen readers when no visible label points at it. */
  label: string;
  className?: string;
};

/** One choice out of a few on a segmented track: a raised thumb travels to the picked segment. */
export function ChoiceSegments<Value extends string>({
  value,
  options,
  onValueChange,
  label,
  className,
}: ChoiceSegmentsProps<Value>) {
  const pressedValues = [value];

  function changeValue(nextValues: unknown[]) {
    const [nextValue] = nextValues;
    const option = options.find((candidate) => candidate.value === nextValue);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <ToggleGroup
      aria-label={label}
      value={pressedValues}
      onValueChange={changeValue}
      travel
      size='sm'
      indicatorClassName={THUMB}
      className={cn('bg-foreground/[0.05] w-full rounded-lg p-0.5', className)}
    >
      {options.map((option) => {
        const OptionGlyph = option.icon;

        return (
          <ToggleGroupItem
            key={option.value}
            value={option.value}
            className='flex-1 rounded-md'
          >
            {OptionGlyph && <OptionGlyph />}
            {option.label}
          </ToggleGroupItem>
        );
      })}
    </ToggleGroup>
  );
}

import {
  AlertCircleIcon,
  ClockIcon,
  UserIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';

/** What sending does to an address: a new invitation, the e-mail again for a pending one, nothing for a member or a typo. */
export type AddressState = 'new' | 'pending' | 'member' | 'invalid';

export type AddressEntry = { email: string; state: AddressState };

export type AddressLook = { color: string; icon: Icon | null; hint: string };

export const ADDRESS_LOOK: Record<AddressState, AddressLook> = {
  new: { color: 'var(--muted-foreground)', icon: null, hint: '' },
  pending: {
    color: 'var(--warning)',
    icon: ClockIcon,
    hint: 'Already invited: they get the e-mail again',
  },
  member: {
    color: 'var(--muted-foreground)',
    icon: UserIcon,
    hint: 'Already in the team: not invited again',
  },
  invalid: {
    color: 'var(--destructive)',
    icon: AlertCircleIcon,
    hint: 'Not a valid e-mail address',
  },
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const TOKEN_SEPARATORS = /[\s,;<>"'()]+/;

export function isEmail(value: string) {
  return EMAIL_PATTERN.test(value);
}

function normalizeAddress(value: string) {
  const trimmed = value.trim();
  return trimmed.toLowerCase();
}

/**
 * The addresses in what was typed or pasted, without repeats. When the text holds an address, the words around it
 * are names copied from a mail client and are left out.
 */
export function splitAddresses(text: string) {
  const tokens = text.split(TOKEN_SEPARATORS);
  const holdsAnAddress = text.includes('@');
  const addresses: string[] = [];
  for (const token of tokens) {
    const address = normalizeAddress(token);
    const isEmpty = address.length === 0;
    const isNameAround = holdsAnAddress && !address.includes('@');
    const isRepeat = addresses.includes(address);
    if (isEmpty || isNameAround || isRepeat) {
      continue;
    }
    addresses.push(address);
  }
  return addresses;
}

export function mergeAddresses(current: string[], added: string[]) {
  const merged = [...current];
  for (const address of added) {
    if (!merged.includes(address)) {
      merged.push(address);
    }
  }
  return merged;
}

export type AddressContext = {
  memberEmails: ReadonlySet<string>;
  pendingEmails: ReadonlySet<string>;
};

export function stateOfAddress(
  email: string,
  context: AddressContext
): AddressState {
  if (!isEmail(email)) {
    return 'invalid';
  }
  if (context.memberEmails.has(email)) {
    return 'member';
  }
  if (context.pendingEmails.has(email)) {
    return 'pending';
  }
  return 'new';
}

export function isSendable(state: AddressState) {
  const isNew = state === 'new';
  const isPending = state === 'pending';
  return isNew || isPending;
}

export function countOf(entries: AddressEntry[], state: AddressState) {
  return entries.filter((entry) => entry.state === state).length;
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

import { SWAP_TRANSITION, swapVariantsOf, type SwapKind } from './motion';

type SwapProps = {
  /** Changes when the content becomes another: the old one leaves while the new one arrives in its place. */
  swapKey: string;
  kind?: SwapKind;
  className?: string;
  /** Classes of the moving content, for example `min-w-0 max-w-full` so a long text can truncate inside. */
  contentClassName?: string;
  children: React.ReactNode;
};

export function Swap({
  swapKey,
  kind = 'icon',
  className,
  contentClassName,
  children,
}: SwapProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion, kind);

  return (
    <span className={cn('relative inline-flex items-center', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          className={cn(
            'inline-flex items-center gap-[inherit] whitespace-nowrap',
            contentClassName
          )}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}
